#include <cudnn.h>
#include <cuda_runtime.h>
#include <stdio.h>

#define CUDNN_CHECK(call) { cudnnStatus_t e = call; if (e != CUDNN_STATUS_SUCCESS) { fprintf(stderr, "cuDNN error %d at %s:%d\n", e, __FILE__, __LINE__); exit(1); } }

static cudnnHandle_t g_cudnn = nullptr;
void ensure_cudnn() {
    if (!g_cudnn) CUDNN_CHECK(cudnnCreate(&g_cudnn));
}

// Conv2d forward: NCHW float32, uses Tensor Cores when available
void gpu_conv2d(const float* input, const float* filter, float* output,
                int N, int C, int H, int W, int K, int R, int S,
                int pad, int stride) {
    ensure_cudnn();
    cudnnTensorDescriptor_t xDesc, yDesc;
    cudnnFilterDescriptor_t wDesc;
    cudnnConvolutionDescriptor_t convDesc;
    CUDNN_CHECK(cudnnCreateTensorDescriptor(&xDesc));
    CUDNN_CHECK(cudnnCreateTensorDescriptor(&yDesc));
    CUDNN_CHECK(cudnnCreateFilterDescriptor(&wDesc));
    CUDNN_CHECK(cudnnCreateConvolutionDescriptor(&convDesc));
    CUDNN_CHECK(cudnnSetTensor4dDescriptor(xDesc, CUDNN_TENSOR_NCHW, CUDNN_DATA_FLOAT, N, C, H, W));
    CUDNN_CHECK(cudnnSetFilter4dDescriptor(wDesc, CUDNN_DATA_FLOAT, CUDNN_TENSOR_NCHW, K, C, R, S));
    CUDNN_CHECK(cudnnSetConvolution2dDescriptor(convDesc, pad, pad, stride, stride, 1, 1, CUDNN_CROSS_CORRELATION, CUDNN_DATA_FLOAT));
    CUDNN_CHECK(cudnnSetConvolutionMathType(convDesc, CUDNN_TENSOR_OP_MATH));
    int outN, outC, outH, outW;
    CUDNN_CHECK(cudnnGetConvolution2dForwardOutputDim(convDesc, xDesc, wDesc, &outN, &outC, &outH, &outW));
    CUDNN_CHECK(cudnnSetTensor4dDescriptor(yDesc, CUDNN_TENSOR_NCHW, CUDNN_DATA_FLOAT, outN, outC, outH, outW));
    cudnnConvolutionFwdAlgo_t algo = CUDNN_CONVOLUTION_FWD_ALGO_IMPLICIT_PRECOMP_GEMM;
    size_t wsSize = 0;
    CUDNN_CHECK(cudnnGetConvolutionForwardWorkspaceSize(g_cudnn, xDesc, wDesc, convDesc, yDesc, algo, &wsSize));
    void* ws = nullptr;
    if (wsSize > 0) cudaMalloc(&ws, wsSize);
    float alpha = 1.0f, beta = 0.0f;
    CUDNN_CHECK(cudnnConvolutionForward(g_cudnn, &alpha, xDesc, input, wDesc, filter, convDesc, algo, ws, wsSize, &beta, yDesc, output));
    if (ws) cudaFree(ws);
    cudnnDestroyTensorDescriptor(xDesc);
    cudnnDestroyTensorDescriptor(yDesc);
    cudnnDestroyFilterDescriptor(wDesc);
    cudnnDestroyConvolutionDescriptor(convDesc);
}

